def getMaxRepetitions(s1, n1, s2, n2):
    if not s1 or not s2 or n1 == 0:
        return 0

    s2_index, count1, count2 = 0, 0, 0
    lookup = {}

    while count1 < n1:
        count1 += 1
        for char in s1:
            if char == s2[s2_index]:
                s2_index += 1
                if s2_index == len(s2):
                    s2_index = 0
                    count2 += 1

        if s2_index in lookup:
            prev_count1, prev_count2 = lookup[s2_index]
            cycle_count1 = count1 - prev_count1
            cycle_count2 = count2 - prev_count2
            remaining_count1 = n1 - count1
            cycles = remaining_count1 // cycle_count1
            count1 += cycles * cycle_count1
            count2 += cycles * cycle_count2
            break
        else:
            lookup[s2_index] = (count1, count2)

    return count2 // n2
